(()=>{var o=document.querySelector(".home-explore");if(o){let n=[...o.querySelectorAll('details[name="home-intent"]')];for(let e of n)e.addEventListener("toggle",()=>{if(e.open)for(let t of n)t!==e&&(t.open=!1)});o.addEventListener("keydown",e=>{if(e.key!=="Escape")return;let t=e.target.closest("details[open]");t&&(t.open=!1,t.querySelector("summary").focus(),e.preventDefault())}),document.addEventListener("click",e=>{if(!o.contains(e.target))for(let t of n)t.open=!1})}})();
